<?php
/** Opt-in PDF preview; existing HTML/Excel previews retain their behaviour. */
function render_native_report_preview(array $options):void {
    $e='report_preview_escape';$title=(string)($options['title']??'Laporan');$url=(string)$options['pdf_url'];
    $palette=[0=>'7228d9',1=>'168a46',2=>'2449d8',3=>'c9252d'][(int)($options['unit']??1)]??'168a46';
    ?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= $e($title) ?> | Preview PDF</title>
    <style>
    *{box-sizing:border-box}:root{--accent:#<?= $palette ?>;--bg:#edf3f0;--card:#fff;--text:#20332a;--muted:#60746b;--line:#d3e2da}html[data-theme=dark]{--bg:#111b24;--card:#1b2935;--text:#eef4f1;--muted:#acbdb5;--line:#344a42}body{margin:0;background:var(--bg);color:var(--text);font:14px/1.5 "Segoe UI",Arial,sans-serif}.pdf-toolbar{display:flex;justify-content:space-between;align-items:center;gap:20px;padding:18px 24px;background:var(--card);border-bottom:1px solid var(--line);position:sticky;top:0;z-index:2}.pdf-toolbar h1{font-size:20px;margin:0 0 5px}.pdf-toolbar p{margin:0;color:var(--muted);font-size:13px}.pdf-actions{display:flex;gap:9px;flex-wrap:wrap}.pdf-button{display:inline-flex;align-items:center;justify-content:center;gap:8px;border:1px solid var(--line);border-radius:10px;padding:10px 15px;min-height:44px;background:var(--card);color:var(--text);font:600 14px "Segoe UI",Arial,sans-serif;text-decoration:none;cursor:pointer}.pdf-button.primary{background:var(--accent);border-color:var(--accent);color:#fff}.pdf-button:focus-visible{outline:2px solid var(--accent);outline-offset:3px}.pdf-button:disabled{opacity:.5;cursor:wait}.pdf-button svg{width:18px;height:18px}.pdf-meta{display:flex;gap:16px;justify-content:center;flex-wrap:wrap;padding:14px;color:var(--muted);font-size:13px}.pdf-stage{max-width:1500px;margin:auto;padding:0 20px 24px}.pdf-stage iframe{width:100%;height:calc(100vh - 170px);min-height:500px;display:block;border:1px solid var(--line);border-radius:12px;background:#fff}.pdf-status{padding:18px;text-align:center;background:var(--card);border:1px solid var(--line);border-radius:12px;margin-bottom:12px}.pdf-fallback{font-size:13px;color:var(--muted)}.pdf-fallback a{color:var(--text)}[hidden]{display:none!important}@media(max-width:700px){.pdf-toolbar{position:relative;align-items:stretch;flex-direction:column;padding:16px}.pdf-actions{display:grid;grid-template-columns:repeat(2,minmax(0,1fr))}.pdf-stage{padding:0 10px 16px}.pdf-toolbar h1{font-size:18px}.pdf-meta{justify-content:start}.pdf-stage iframe{height:70vh}}@media print{body>*{display:none!important}}
    </style><script>try{document.documentElement.dataset.theme=localStorage.getItem('spp_theme')||'light'}catch(e){}</script></head><body data-native-pdf data-pdf-url="<?= $e($url) ?>" data-filename="<?= $e(preg_replace('/[^A-Za-z0-9_-]+/','-',strtolower($title)).'.pdf') ?>">
    <header class="pdf-toolbar"><div><h1><?= $e($title) ?></h1><p><?= $e($options['subtitle']??'') ?></p></div><nav class="pdf-actions" aria-label="Tindakan laporan"><a class="pdf-button" href="<?= $e($options['back_url']??'javascript:history.back()') ?>">Kembali</a><button class="pdf-button" type="button" data-pdf-print disabled><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M6 9V3h12v6M6 17H3V9h18v8h-3"/><path d="M6 14h12v7H6z"/></svg>Cetak</button><a class="pdf-button primary" data-pdf-download href="<?= $e($options['download_url']??$url) ?>">Download PDF</a></nav></header>
    <div class="pdf-meta"><span>A4 <?= ($options['orientation']??'landscape')==='landscape'?'Lanskap':'Potret' ?></span><span><?= number_format((int)($options['row_count']??0)) ?> data</span><span data-pdf-generated><?= $e($options['generated']??'') ?></span></div>
    <main class="pdf-stage"><div class="pdf-status" role="status" aria-live="polite"><span data-pdf-message>Menyiapkan PDF…</span> <button class="pdf-button" data-pdf-retry type="button" hidden>Coba Lagi</button></div><iframe data-pdf-frame title="<?= $e('PDF '.$title) ?>" hidden></iframe><p class="pdf-fallback">Tampilan dan cetak memakai PDF yang sama. <a href="<?= $e($url) ?>" target="_blank" rel="noopener">Buka PDF di tab baru</a> jika penampil tidak tersedia.</p></main>
    <script src="<?= $e((str_contains(str_replace('\\','/',$_SERVER['SCRIPT_NAME']??''),'/laporan/')?'../':'').'assets/js/report_pdf_preview.js?v='.filemtime(__DIR__.'/../assets/js/report_pdf_preview.js')) ?>"></script></body></html><?php exit;
}
